#!/usr/bin/env bash
set -u
G='\033[0;32m';R='\033[0;31m';C='\033[0;36m';W='\033[1;37m';N='\033[0m'
banner(){ clear 2>/dev/null||true; echo -e "${C}╔══════════════════════════════════════════════════╗${N}"; echo -e "${C}║${W}                     APNELY                     ${C}║${N}"; echo -e "${C}║${W}                     NGINX                      ${C}║${N}"; echo -e "${C}║${W}              MADE BY ARNAV SHARMA             ${C}║${N}"; echo -e "${C}╚══════════════════════════════════════════════════╝${N}"; echo; }; ok(){  echo -e "${G}✓${N} $1"; }; bad(){  echo -e "${R}✗${N} $1"; }; pause(){  read -r -p 'Press Enter to continue...' _; }; root(){  [ "$(id -u)" -eq 0 ]|| { bad 'Run as root.';exit 1;}; }
install_ng(){  apt-get update||true; apt-get install -y nginx; systemctl enable --now nginx; systemctl is-active --quiet nginx&&ok 'Nginx is running'||bad 'Nginx failed'; pause; }; remove_ng(){  read -r -p 'Remove Nginx? [y/N]: ' a; case "$a" in y|Y) systemctl stop nginx 2>/dev/null||true; apt-get remove -y nginx nginx-common||true; ok 'Nginx removed';;esac;pause; }; status(){  banner;systemctl status nginx --no-pager||true;pause;}; restart(){  systemctl restart nginx&&ok 'Nginx restarted'||bad 'Nginx failed';pause;}; menu(){ root;while true;do banner;echo '[1] Install Nginx';echo '[2] Uninstall Nginx';echo '[3] Restart Nginx';echo '[4] Nginx Status';echo '[5] Back';read -r -p 'Select: ' c;case "$c" in 1)install_ng;;2)remove_ng;;3)restart;;4)status;;5)return;;*)bad 'Invalid option';;esac;done;};menu
